<div class="navigation-progress" role="progressbar" aria-label="Loading page"></div>
<style>.navigation-progress { position: absolute; inset: 0 auto auto 0; height: 3px; width: 35%; background: var(--color-primary); animation: progress 1.2s ease-in-out infinite alternate; } @keyframes progress { to { transform: translateX(180%); } } @media(prefers-reduced-motion:reduce) { .navigation-progress { animation: none; width: 100%; } }</style>
